function developerBeep(freq,duration,at){
 const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.frequency.value=freq;osc.connect(gain);gain.connect(audioCtx.destination);
 gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(.04,at+.005);gain.gain.setValueAtTime(.04,at+duration-.01);gain.gain.linearRampToValueAtTime(0,at+duration);osc.start(at);osc.stop(at+duration);developerAudio.push(osc);
}
function cancelDeveloperGuidance(){clearTimeout(developerTimer);developerTimer=null;developerPhase=null;developerQueue=[];for(const osc of developerAudio)try{osc.stop()}catch{}developerAudio=[];}
function scheduleDeveloperAudio(c){
 developerAudio=[];const at=t=>audioCtx.currentTime+t-now();
 for(let i=3;i>0;i--)developerBeep(440,.07,Math.max(audioCtx.currentTime,at(c.action_onset-i)));
 for(let i=0;i<20;i++)if(c.action!=='blink'||i%2===0)developerBeep(850,.045,Math.max(audioCtx.currentTime,at(c.action_onset+i)));
 developerBeep(500,.7,Math.max(audioCtx.currentTime,at(c.ends)));
}
