 const ratios=d.last.std_ratio_action_to_rest;const result=d.last.requested_action==='free_recording'?'Unlabeled example saved. Tell me what you recorded.':ratios?boot.channels.map((ch,i)=>`${ch}: ${ratios[i].toFixed(1)}× rest variability`).join(' · '):'Insufficient clean data for a comparison; raw samples retained.';
 if(!d.last.cancelled&&developerQueue.length&&!state.stale){developerPhase={kind:'recover',until:now()+5};developerTimer=setTimeout(()=>{developerPhase=null;startNextDeveloper()},5000)}else if(state.stale)cancelDeveloperGuidance();
