{preflightOverride=false;preflightContactRejected=false;$('preflightInstruction').textContent=participantInstruction(protocol.id);$('preflightQuality').hidden=true;$('preflightTroubleshoot').open=false;$('preflight').showModal();$('cancelPreflight').focus({preventScroll:true});renderPreflight()};$('confirmStart').onclick=beginRun;$('cancelPreflight').onclick=()=>$('preflight').close();$('stop').onclick=()=>endRun();$('stageStop').onclick=()=>endRun();$('libraryNav').onclick=openLibrary;$('closeLibrary').onclick=()=>$('library').close();$('importButton').onclick=importImages;$('sessionsNav').onclick=async()=>{try{const sessions=await api('sessions');$('historyList').replaceChildren();for(const s of sessions){const p=document.createElement('p'),a=document.createElement('a');a.href='/api/archive/'+s.id;a.textContent=`${s.title} · ${s.source} · ${new Date(s.started*1000).toLocaleString()} · Download ZIP`;p.append(a);$('historyList').append(p)}if(!sessions.length)$('historyList').textContent='Your recordings will appear here.';$('history').showModal()}catch(e){toast(e.message)}};$('closeHistory').onclick=()=>$('history').close();document.addEventListener('keydown',e=>{if(active&&e.key==='Escape'){e.preventDefault();endRun()}else if(active&&responseHandler){e.preventDefault();responseHandler(e.key)}});document.addEventListener('visibilitychange',()=>{if(active&&document.hidden)marker({kind:'timing_issue',reason:'tab hidden'}).finally(()=>endRun('presentation tab hidden'))});window.addEventListener('beforeunload',e=>{if(active){e.preventDefault();e.returnValue=''}});window.addEventListener('resize',()=>{renderRevision='';render()});
